import{_ as l,c as e,o as i,a_ as r}from"./chunks/framework.CC6ejVHf.js";const p=JSON.parse('{"title":"工作与项目经历","description":"","frontmatter":{},"headers":[],"relativePath":"zh/zjy/work copy 2.md","filePath":"zh/zjy/work copy 2.md","lastUpdated":null}'),t={name:"zh/zjy/work copy 2.md"};function o(n,a,h,s,u,d){return i(),e("div",null,a[0]||(a[0]=[r('<h1 id="工作与项目经历" tabindex="-1">工作与项目经历 <a class="header-anchor" href="#工作与项目经历" aria-label="Permalink to &quot;工作与项目经历&quot;">​</a></h1><h2 id="个人概况" tabindex="-1">个人概况 <a class="header-anchor" href="#个人概况" aria-label="Permalink to &quot;个人概况&quot;">​</a></h2><p>具有近 <strong>6 年前端开发经验</strong>，主要使用 Vue 2、Vue 3 和 TypeScript 参与企业级 Web、移动端及可视化项目。工作内容涵盖业务功能开发、组件设计、地图与图表应用、大屏场景搭建、性能优化和项目发布。</p><h2 id="工作经历" tabindex="-1">工作经历 <a class="header-anchor" href="#工作经历" aria-label="Permalink to &quot;工作经历&quot;">​</a></h2><h3 id="东软集团-南京-股份有限公司" tabindex="-1">东软集团（南京）股份有限公司 <a class="header-anchor" href="#东软集团-南京-股份有限公司" aria-label="Permalink to &quot;东软集团（南京）股份有限公司&quot;">​</a></h3><p><strong>前端开发工程师</strong>｜2021.09—2026.06</p><ul><li>参与烟草物流、配送、零售户应用、经济运行管控等项目的前端开发与维护。</li><li>负责复杂业务页面、可复用组件、数据可视化和地图相关功能的设计与实现。</li><li>参与系统迁移、问题排查、性能优化及打包发布。</li></ul><h3 id="江苏数字矩阵科技有限公司" tabindex="-1">江苏数字矩阵科技有限公司 <a class="header-anchor" href="#江苏数字矩阵科技有限公司" aria-label="Permalink to &quot;江苏数字矩阵科技有限公司&quot;">​</a></h3><p><strong>Web 前端开发工程师</strong>｜2020.08—2021.09</p><ul><li>负责 PC 端和微信小程序页面开发。</li><li>参与页面性能优化及业务功能迭代。</li></ul><h2 id="项目经历" tabindex="-1">项目经历 <a class="header-anchor" href="#项目经历" aria-label="Permalink to &quot;项目经历&quot;">​</a></h2><h3 id="河北烟草智慧物流平台-pc-端-2-0" tabindex="-1">河北烟草智慧物流平台 PC 端 2.0 <a class="header-anchor" href="#河北烟草智慧物流平台-pc-端-2-0" aria-label="Permalink to &quot;河北烟草智慧物流平台 PC 端 2.0&quot;">​</a></h3><p><strong>技术栈：</strong> Vue 3、TypeScript、ECharts、Element Plus、高德地图、Vite、Vuex</p><ul><li>参与 2.0 系统迁移，整理并迁移可复用组件。</li><li>搭建可配置的动态首页，支持菜单自定义、消息展示与阅读、动态数据卡片及多层级弹窗。</li><li>封装多种卡片组件，根据业务类型渲染饼图、柱状对比图和排行榜等内容。</li><li>处理省局与地市之间的数据和页面权限差异。</li><li>参与 TMS、WMS 流程页面开发、问题修复、项目发布和性能优化。</li></ul><h3 id="云南、河北烟草大屏可视化平台" tabindex="-1">云南、河北烟草大屏可视化平台 <a class="header-anchor" href="#云南、河北烟草大屏可视化平台" aria-label="Permalink to &quot;云南、河北烟草大屏可视化平台&quot;">​</a></h3><p><strong>技术栈：</strong> Vue 3、TypeScript、Three.js、ECharts、Element Plus、高德地图、Vuex</p><ul><li>参与大屏系统搭建，并主导采用 Three.js 构建三维展示场景。</li><li>绘制三维地图模型，完成车辆坐标转换与场景渲染，并实现三维文字、灯光和地市交互展示。</li><li>实现车辆模型移动、轮胎效果、车辆在途信息与高德地图线路展示，以及绿色园区场景。</li><li>处理页面数据自动刷新和场景资源清理，降低长时间运行时的资源占用风险。</li></ul><h3 id="石家庄烟草物流指挥调度中心" tabindex="-1">石家庄烟草物流指挥调度中心 <a class="header-anchor" href="#石家庄烟草物流指挥调度中心" aria-label="Permalink to &quot;石家庄烟草物流指挥调度中心&quot;">​</a></h3><p><strong>技术栈：</strong> Vue 2、ECharts、Three.js</p><ul><li>参与从烟草大屏项目中拆分出的地市级指挥调度系统开发。</li><li>负责首页及相关展示功能开发。</li></ul><h3 id="云南、河北烟草送货员-app" tabindex="-1">云南、河北烟草送货员 APP <a class="header-anchor" href="#云南、河北烟草送货员-app" aria-label="Permalink to &quot;云南、河北烟草送货员 APP&quot;">​</a></h3><p><strong>技术栈：</strong> Vue 2、Mint UI、Vant、高德地图</p><ul><li>参与送货业务流程开发，包括扫码签收、残损烟登记、卷烟盘点和配送在途信息展示。</li><li>实现客户与送货线路信息、送货导航，以及签字、拍照、扫码等签收方式。</li></ul><h3 id="钉钉零售户应用" tabindex="-1">钉钉零售户应用 <a class="header-anchor" href="#钉钉零售户应用" aria-label="Permalink to &quot;钉钉零售户应用&quot;">​</a></h3><p><strong>技术栈：</strong> Vue 3、TypeScript、WebSocket</p><ul><li>负责应用搭建并主导前端开发。</li><li>实现收货二维码及有效期展示，与送货员 APP 的扫码签收流程配合。</li><li>开发送货进度、订单信息和连锁店铺切换功能。</li><li>配合阿里巴巴相关人员联调钉钉免登录流程。</li></ul><h3 id="经济运行管控平台-pc-端及移动端" tabindex="-1">经济运行管控平台（PC 端及移动端） <a class="header-anchor" href="#经济运行管控平台-pc-端及移动端" aria-label="Permalink to &quot;经济运行管控平台（PC 端及移动端）&quot;">​</a></h3><p><strong>PC 端技术栈：</strong> Vue 2、Element UI、ECharts<br><strong>移动端技术栈：</strong> Vue 2、H5、Vant、ECharts</p><ul><li>参与平台维护，保障现有功能稳定运行。</li><li>开发卷烟报表页面，并处理移动端适配和页面鉴权。</li></ul><h3 id="扬州市线路规划" tabindex="-1">扬州市线路规划 <a class="header-anchor" href="#扬州市线路规划" aria-label="Permalink to &quot;扬州市线路规划&quot;">​</a></h3><p><strong>技术栈：</strong> Vue 2、Element UI、高德地图</p><ul><li>使用高德地图展示海量点位并实现点聚合。</li><li>支持框选点位及批量颜色调整，并配合后端展示自动规划线路，通过颜色区分线路点位。</li></ul><h3 id="多彩旅客服务系统" tabindex="-1">多彩旅客服务系统 <a class="header-anchor" href="#多彩旅客服务系统" aria-label="Permalink to &quot;多彩旅客服务系统&quot;">​</a></h3><p><strong>技术栈：</strong> Vue 2、H5、Vant</p><ul><li>面向乘务人员开发升舱、会员服务、乘务长日志及日志填报等功能。</li><li>实现航班数据下载与本地缓存、旅客信息展示及行李运输相关流程，包括不正常行李处理。</li></ul><h3 id="证企通微信小程序" tabindex="-1">证企通微信小程序 <a class="header-anchor" href="#证企通微信小程序" aria-label="Permalink to &quot;证企通微信小程序&quot;">​</a></h3><p><strong>技术栈：</strong> 微信原生小程序、Vant、OCR</p><ul><li>参与小程序前端开发，实现证件 OCR 识别及订单支付相关流程。</li></ul><h3 id="证企通-web-平台" tabindex="-1">证企通 Web 平台 <a class="header-anchor" href="#证企通-web-平台" aria-label="Permalink to &quot;证企通 Web 平台&quot;">​</a></h3><p><strong>技术栈：</strong> Vue 2、Element UI</p><ul><li>参与 Web 平台前端开发。</li></ul><h3 id="小说生成聊天工具-业余项目" tabindex="-1">小说生成聊天工具（业余项目） <a class="header-anchor" href="#小说生成聊天工具-业余项目" aria-label="Permalink to &quot;小说生成聊天工具（业余项目）&quot;">​</a></h3><ul><li>集成 Gemini Pro API，支持导入文件并识别内容。</li><li>根据文件内容生成小说章节，并以流式方式呈现对话结果。</li></ul>',43)]))}const b=l(t,[["render",o]]);export{p as __pageData,b as default};
